// Example of a Server Component fetching data directly
async function InventoryList() {
  // Fetching data on the server avoids client-side API waterfalls
  const data = await fetch('https://api.logistics.internal/stock');
  const inventory = await data.json();
  return <ul>{inventory.map(item => <li key={item.id}>{item.name}</li>)}</ul>;
}
